1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_SURCHARGE = 0.10;
11	
12	const BASE_PREMIUM: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	};
17	
18	const roundUp = (n: number): number => Math.ceil(n - 1e-9);
19	
20	const sumItemBases = (items: Item[]): number =>
21	  items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
22	
23	const computePremium = (items: Item[]): number =>
24	  roundUp(sumItemBases(items) * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
25	
26	export const runScenario = (scenario: Scenario): ScenarioResult => ({
27	  results: scenario.steps.map((step) => ({ premium: computePremium(step.items) })),
28	});
