const PROCESSING_FEE = 5;
const FIRST_INSURANCE_MULTIPLIER = 1.10;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const roundUp = (n: number): number => Math.ceil(n - 1e-9);

const basePremiumOf = (item: Item): number => BASE_PREMIUM[item.type];

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const computeQuotePremium = (items: Item[]): number =>
  roundUp(sumBasePremiums(items) * FIRST_INSURANCE_MULTIPLIER + PROCESSING_FEE);

